export type HexColor = string;

export interface SlideSize {
  width: number;
  height: number;
}

export interface Bounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

export type HorizontalAlignment = "left" | "center" | "right";
export type VerticalAlignment = "top" | "middle" | "bottom";

export interface TextStyle {
  fontFace?: string;
  fontSize?: number;
  color?: HexColor;
  bold?: boolean;
  italic?: boolean;
  align?: HorizontalAlignment;
  verticalAlign?: VerticalAlignment;
  margin?: number;
  breakLine?: boolean;
  bullet?: boolean;
}

export interface TextElement extends Bounds {
  type: "text";
  text: string;
  style?: TextStyle;
}

export type ShapeKind = "rectangle" | "rounded-rectangle" | "line" | "ellipse";

export interface ShapeElement extends Bounds {
  type: "shape";
  shape: ShapeKind;
  fill?: HexColor;
  stroke?: HexColor;
  strokeWidth?: number;
}

export type ChartKind = "bar" | "line";

export interface ChartSeries {
  name: string;
  values: number[];
}

export interface ChartElement extends Bounds {
  type: "chart";
  chart: ChartKind;
  categories: string[];
  series: ChartSeries[];
  colors: HexColor[];
  showValues?: boolean;
  valueFormat?: string;
  altText: string;
}

export type SlideElement = TextElement | ShapeElement | ChartElement;

export type WarningType = "text-overflow" | "content-truncated" | "layout-overflow";

export interface LayoutWarning {
  type: WarningType;
  component: string;
  field: string;
  message: string;
}

export interface SlideDefinition {
  elements: SlideElement[];
  background: HexColor;
  warnings: LayoutWarning[];
  speakerNotes?: string;
}

export interface ComponentContext {
  size: SlideSize;
  theme: Theme;
}

export type SlideComponent = (context: ComponentContext) => SlideDefinition;

export interface Theme {
  name: string;
  fonts: {
    heading: string;
    body: string;
    mono: string;
  };
  colors: {
    background: HexColor;
    foreground: HexColor;
    muted: HexColor;
    mutedForeground: HexColor;
    accent: HexColor;
    accentForeground: HexColor;
    border: HexColor;
    success: HexColor;
    danger: HexColor;
  };
  typography: {
    display: number;
    title: number;
    heading: number;
    body: number;
    caption: number;
  };
  spacing: {
    xs: number;
    sm: number;
    md: number;
    lg: number;
    xl: number;
  };
}

import type { Theme } from "./types.js";

export const defaultTheme: Theme = {
  name: "default",
  fonts: {
    heading: "Aptos Display",
    body: "Aptos",
    mono: "Aptos Mono",
  },
  colors: {
    background: "F7F7F5",
    foreground: "161616",
    muted: "EAEAE6",
    mutedForeground: "666660",
    accent: "171717",
    accentForeground: "FFFFFF",
    border: "D8D8D2",
    success: "171717",
    danger: "666666",
  },
  typography: {
    display: 38,
    title: 26,
    heading: 18,
    body: 14,
    caption: 10,
  },
  spacing: {
    xs: 0.08,
    sm: 0.16,
    md: 0.28,
    lg: 0.48,
    xl: 0.72,
  },
};

export function defineTheme(theme: Theme): Theme {
  return theme;
}

export function mergeTheme(base: Theme, overrides: Partial<Theme>): Theme {
  return {
    ...base,
    ...overrides,
    fonts: { ...base.fonts, ...overrides.fonts },
    colors: { ...base.colors, ...overrides.colors },
    typography: { ...base.typography, ...overrides.typography },
    spacing: { ...base.spacing, ...overrides.spacing },
  };
}

import type { Bounds } from "./types.js";

export const WIDESCREEN = { width: 13.333, height: 7.5 } as const;

export function inset(bounds: Bounds, amount: number): Bounds {
  return {
    x: bounds.x + amount,
    y: bounds.y + amount,
    width: Math.max(0, bounds.width - amount * 2),
    height: Math.max(0, bounds.height - amount * 2),
  };
}

export function equalColumns(bounds: Bounds, count: number, gap: number): Bounds[] {
  if (!Number.isInteger(count) || count < 1) {
    throw new RangeError("Column count must be a positive integer.");
  }
  const width = (bounds.width - gap * (count - 1)) / count;
  if (width <= 0) {
    throw new RangeError("Columns and gaps do not fit inside the available width.");
  }
  return Array.from({ length: count }, (_, index) => ({
    x: bounds.x + index * (width + gap),
    y: bounds.y,
    width,
    height: bounds.height,
  }));
}

export function equalRows(bounds: Bounds, count: number, gap: number): Bounds[] {
  if (!Number.isInteger(count) || count < 1) {
    throw new RangeError("Row count must be a positive integer.");
  }
  const height = (bounds.height - gap * (count - 1)) / count;
  if (height <= 0) {
    throw new RangeError("Rows and gaps do not fit inside the available height.");
  }
  return Array.from({ length: count }, (_, index) => ({
    x: bounds.x,
    y: bounds.y + index * (height + gap),
    width: bounds.width,
    height,
  }));
}

export function isInside(inner: Bounds, outer: Bounds): boolean {
  const epsilon = 0.0001;
  return (
    inner.x + epsilon >= outer.x &&
    inner.y + epsilon >= outer.y &&
    inner.x + inner.width <= outer.x + outer.width + epsilon &&
    inner.y + inner.height <= outer.y + outer.height + epsilon
  );
}

import type { Bounds, ShapeElement, ShapeKind, TextElement, TextStyle } from "./types.js";

export function text(text: string, bounds: Bounds, style?: TextStyle): TextElement {
  return style
    ? { type: "text", text, ...bounds, style }
    : { type: "text", text, ...bounds };
}

export interface ShapeOptions {
  fill?: string;
  stroke?: string;
  strokeWidth?: number;
}

export function shape(kind: ShapeKind, bounds: Bounds, options: ShapeOptions = {}): ShapeElement {
  return { type: "shape", shape: kind, ...bounds, ...options };
}

import type { Bounds, LayoutWarning, SlideDefinition, SlideElement } from "./types.js";

export function createSlide(background: string): SlideBuilder {
  return new SlideBuilder(background);
}

export class SlideBuilder {
  readonly elements: SlideElement[] = [];
  readonly warnings: LayoutWarning[] = [];

  constructor(readonly background: string) {}

  add(...elements: SlideElement[]): this {
    this.elements.push(...elements);
    return this;
  }

  warn(warning: LayoutWarning): this {
    this.warnings.push(warning);
    return this;
  }

  build(speakerNotes?: string): SlideDefinition {
    return speakerNotes === undefined
      ? { background: this.background, elements: this.elements, warnings: this.warnings }
      : { background: this.background, elements: this.elements, warnings: this.warnings, speakerNotes };
  }
}

export function isInsideSlide(element: Bounds, slide: Bounds): boolean {
  const epsilon = 0.0001;
  return (
    element.x >= slide.x - epsilon &&
    element.y >= slide.y - epsilon &&
    element.x + element.width <= slide.x + slide.width + epsilon &&
    element.y + element.height <= slide.y + slide.height + epsilon
  );
}

export function assertSlideBounds(definition: SlideDefinition, width: number, height: number): void {
  const slide = { x: 0, y: 0, width, height };
  const invalid = definition.elements.find((element) => !isInsideSlide(element, slide));
  if (invalid) {
    throw new RangeError(
      `Slide element exceeds slide bounds: ${invalid.type} at (${invalid.x}, ${invalid.y}, ${invalid.width}, ${invalid.height}).`,
    );
  }
}

import PptxGenJS from "pptxgenjs";
import type { ChartElement, ShapeElement, ShapeKind, SlideDefinition, TextElement } from "./types.js";

const shapeMap: Record<ShapeKind, PptxGenJS.ShapeType> = {
  rectangle: "rect" as PptxGenJS.ShapeType,
  "rounded-rectangle": "roundRect" as PptxGenJS.ShapeType,
  line: "line" as PptxGenJS.ShapeType,
  ellipse: "ellipse" as PptxGenJS.ShapeType,
};

function renderText(slide: PptxGenJS.Slide, element: TextElement): void {
  slide.addText(element.text, {
    x: element.x,
    y: element.y,
    w: element.width,
    h: element.height,
    ...(element.style?.fontFace !== undefined && { fontFace: element.style.fontFace }),
    ...(element.style?.fontSize !== undefined && { fontSize: element.style.fontSize }),
    ...(element.style?.color !== undefined && { color: element.style.color }),
    ...(element.style?.bold !== undefined && { bold: element.style.bold }),
    ...(element.style?.italic !== undefined && { italic: element.style.italic }),
    ...(element.style?.align !== undefined && { align: element.style.align }),
    ...(element.style?.verticalAlign !== undefined && { valign: element.style.verticalAlign }),
    margin: element.style?.margin ?? 0,
    ...(element.style?.breakLine !== undefined && { breakLine: element.style.breakLine }),
    ...(element.style?.bullet !== undefined && { bullet: element.style.bullet }),
    fit: "shrink",
  });
}

function renderShape(slide: PptxGenJS.Slide, element: ShapeElement): void {
  slide.addShape(shapeMap[element.shape], {
    x: element.x,
    y: element.y,
    w: element.width,
    h: element.height,
    fill: element.fill ? { color: element.fill } : { color: "FFFFFF", transparency: 100 },
    line: element.stroke
      ? { color: element.stroke, width: element.strokeWidth ?? 1 }
      : { color: element.fill ?? "FFFFFF", transparency: 100 },
  });
}

function renderChart(slide: PptxGenJS.Slide, element: ChartElement): void {
  slide.addChart(
    element.chart,
    element.series.map((series) => ({ name: series.name, labels: element.categories, values: series.values })),
    {
      x: element.x,
      y: element.y,
      w: element.width,
      h: element.height,
      chartColors: element.colors,
      showLegend: element.series.length > 1,
      legendPos: "b",
      showValue: element.showValues ?? false,
      ...(element.valueFormat !== undefined && { dataLabelFormatCode: element.valueFormat }),
      valGridLine: { color: "E5E5E5" },
      showTitle: false,
      ...(element.valueFormat !== undefined && { valAxisLabelFormatCode: element.valueFormat }),
      lineDataSymbol: "circle",
      lineSize: 2.5,
      catAxisLabelFontFace: "Aptos",
      valAxisLabelFontFace: "Aptos",
      altText: element.altText,
    },
  );
}

export function renderSlide(presentation: PptxGenJS, definition: SlideDefinition): void {
  const slide = presentation.addSlide();
  slide.background = { color: definition.background };
  for (const element of definition.elements) {
    if (element.type === "text") renderText(slide, element);
    else if (element.type === "shape") renderShape(slide, element);
    else renderChart(slide, element);
  }
  if (definition.speakerNotes) slide.addNotes(definition.speakerNotes);
}

import PptxGenJS from "pptxgenjs";
import { WIDESCREEN } from "./layout.js";
import { renderSlide } from "./renderer.js";
import { assertSlideBounds } from "./slide.js";
import { defaultTheme } from "./theme.js";
import type { LayoutWarning, SlideComponent, SlideDefinition, SlideSize, Theme } from "./types.js";

export interface PresentationOptions {
  theme?: Theme;
  author?: string;
  company?: string;
  title?: string;
  subject?: string;
  size?: SlideSize;
}

export interface Presentation {
  readonly slides: readonly SlideDefinition[];
  readonly warnings: readonly LayoutWarning[];
  add(component: SlideComponent | SlideDefinition): Presentation;
  write(fileName: string): Promise<string>;
  toBlob(): Promise<Blob>;
  toPptxGenJS(): PptxGenJS;
}

export function createPresentation(options: PresentationOptions = {}): Presentation {
  const theme = options.theme ?? defaultTheme;
  const size = options.size ?? WIDESCREEN;
  const slides: SlideDefinition[] = [];

  function toPptxGenJS(): PptxGenJS {
    const pptx = new PptxGenJS();
    const isWide = size.width === WIDESCREEN.width && size.height === WIDESCREEN.height;
    if (isWide) {
      pptx.layout = "LAYOUT_WIDE";
    } else {
      pptx.defineLayout({ name: "PPTCN_CUSTOM", width: size.width, height: size.height });
      pptx.layout = "PPTCN_CUSTOM";
    }
    pptx.author = options.author ?? "pptcn";
    pptx.company = options.company ?? "";
    pptx.title = options.title ?? "pptcn presentation";
    pptx.subject = options.subject ?? "Generated with pptcn";
    pptx.theme = {
      headFontFace: theme.fonts.heading,
      bodyFontFace: theme.fonts.body,
    };
    for (const slide of slides) renderSlide(pptx, slide);
    return pptx;
  }

  const api: Presentation = {
    get slides() {
      return slides;
    },
    get warnings() {
      return slides.flatMap((slide) => slide.warnings);
    },
    add(component) {
      const definition = typeof component === "function" ? component({ size, theme }) : component;
      assertSlideBounds(definition, size.width, size.height);
      slides.push(definition);
      return api;
    },
    async write(fileName) {
      const { dirname, resolve } = await import("node:path");
      const { mkdir } = await import("node:fs/promises");
      const outputPath = resolve(fileName);
      await mkdir(dirname(outputPath), { recursive: true });
      return toPptxGenJS().writeFile({ fileName: outputPath, compression: true });
    },
    toBlob() {
      return toPptxGenJS().write({ outputType: "blob" }) as Promise<Blob>;
    },
    toPptxGenJS,
  };
  return api;
}

import type { LayoutWarning } from "../core/types.js";

export interface ConstrainedText {
  text: string;
  warning?: LayoutWarning;
}

export function constrainText(
  text: string,
  maxCharacters: number,
  component: string,
  field: string,
): ConstrainedText {
  const normalized = text.trim();
  if (normalized.length <= maxCharacters) return { text: normalized };
  return {
    text: `${normalized.slice(0, Math.max(0, maxCharacters - 1)).trimEnd()}…`,
    warning: {
      type: "content-truncated",
      component,
      field,
      message: `${field} exceeded ${maxCharacters} characters and was truncated.`,
    },
  };
}

export function requireText(value: string, field: string): string {
  const normalized = value.trim();
  if (!normalized) throw new TypeError(`${field} cannot be empty.`);
  return normalized;
}

import type { Bounds, LayoutWarning, SlideElement, Theme } from "../core/types.js";
import { constrainText, requireText } from "../utils/content.js";

export interface SlideHeadingOptions {
  title: string;
  eyebrow?: string | undefined;
  bounds: Bounds;
  theme: Theme;
  component: string;
}

export function slideHeading(options: SlideHeadingOptions): {
  elements: SlideElement[];
  warnings: LayoutWarning[];
  contentTop: number;
} {
  const { bounds, theme, component } = options;
  const title = constrainText(requireText(options.title, "title"), 72, component, "title");
  const elements: SlideElement[] = [];
  const warnings: LayoutWarning[] = [];
  let titleY = bounds.y;

  if (options.eyebrow) {
    const eyebrow = constrainText(options.eyebrow, 40, component, "eyebrow");
    elements.push({
      type: "text",
      text: eyebrow.text.toUpperCase(),
      x: bounds.x,
      y: bounds.y,
      width: bounds.width,
      height: 0.25,
      style: {
        fontFace: theme.fonts.body,
        fontSize: theme.typography.caption,
        color: theme.colors.accent,
        bold: true,
        margin: 0,
      },
    });
    if (eyebrow.warning) warnings.push(eyebrow.warning);
    titleY += 0.38;
  }

  elements.push({
    type: "text",
    text: title.text,
    x: bounds.x,
    y: titleY,
    width: bounds.width,
    height: 0.58,
    style: {
      fontFace: theme.fonts.heading,
      fontSize: theme.typography.title,
      color: theme.colors.foreground,
      bold: true,
      margin: 0,
    },
  });
  if (title.warning) warnings.push(title.warning);

  return { elements, warnings, contentTop: titleY + 0.88 };
}

export function footerElement(footer: string | undefined, theme: Theme, width: number, height: number): SlideElement | undefined {
  if (!footer?.trim()) return undefined;
  return {
    type: "text",
    text: footer.trim(),
    x: 0.72,
    y: height - 0.42,
    width: width - 1.44,
    height: 0.18,
    style: {
      fontFace: theme.fonts.body,
      fontSize: 8,
      color: theme.colors.mutedForeground,
      margin: 0,
      align: "right",
    },
  };
}

import { equalColumns } from "../core/layout.js";
import { createSlide } from "../core/slide.js";
import type { Bounds, LayoutWarning, SlideComponent, SlideElement, Theme } from "../core/types.js";
import { constrainText, requireText } from "../utils/content.js";
import { footerElement, slideHeading } from "./shared.js";

export interface ComparisonSide {
  title: string;
  subtitle?: string;
  points: string[];
  accent?: "primary" | "muted" | "success";
}

export interface ComparisonSlideProps {
  title: string;
  eyebrow?: string;
  left: ComparisonSide;
  right: ComparisonSide;
  footer?: string;
}

function comparisonPanel(side: ComparisonSide, bounds: Bounds, theme: Theme, field: "left" | "right") {
  if (side.points.length < 1 || side.points.length > 6) throw new RangeError(`${field}.points requires between 1 and 6 items.`);
  const title = constrainText(requireText(side.title, `${field}.title`), 40, "ComparisonSlide", `${field}.title`);
  const subtitle = side.subtitle ? constrainText(side.subtitle, 76, "ComparisonSlide", `${field}.subtitle`) : undefined;
  const warnings: LayoutWarning[] = [title.warning, subtitle?.warning].filter((warning): warning is LayoutWarning => warning !== undefined);
  const accentColor = side.accent === "success" ? theme.colors.success : side.accent === "muted" ? theme.colors.mutedForeground : theme.colors.accent;
  const elements: SlideElement[] = [
    { type: "shape", shape: "rectangle", ...bounds, fill: "FFFFFF", stroke: theme.colors.border, strokeWidth: 0.8 },
    { type: "shape", shape: "rectangle", x: bounds.x, y: bounds.y, width: 0.08, height: bounds.height, fill: accentColor },
    {
      type: "text", text: title.text, x: bounds.x + 0.42, y: bounds.y + 0.38, width: bounds.width - 0.84, height: 0.38,
      style: { fontFace: theme.fonts.heading, fontSize: theme.typography.heading, color: theme.colors.foreground, bold: true, margin: 0 },
    },
  ];
  let pointsY = bounds.y + 1.15;
  if (subtitle) {
    elements.push({
      type: "text", text: subtitle.text, x: bounds.x + 0.42, y: bounds.y + 0.8, width: bounds.width - 0.84, height: 0.4,
      style: { fontFace: theme.fonts.body, fontSize: 10, color: theme.colors.mutedForeground, margin: 0 },
    });
    pointsY += 0.36;
  }
  const available = bounds.y + bounds.height - pointsY - 0.28;
  const itemHeight = Math.min(0.58, available / side.points.length);
  side.points.forEach((point, index) => {
    const constrained = constrainText(requireText(point, `${field}.points[${index}]`), 92, "ComparisonSlide", `${field}.points[${index}]`);
    if (constrained.warning) warnings.push(constrained.warning);
    elements.push({
      type: "shape", shape: "ellipse", x: bounds.x + 0.44, y: pointsY + index * itemHeight + 0.12, width: 0.09, height: 0.09, fill: accentColor,
    });
    elements.push({
      type: "text", text: constrained.text, x: bounds.x + 0.68, y: pointsY + index * itemHeight, width: bounds.width - 1.1, height: itemHeight,
      style: { fontFace: theme.fonts.body, fontSize: 12, color: theme.colors.foreground, margin: 0, verticalAlign: "middle" },
    });
  });
  return { elements, warnings };
}

export function ComparisonSlide(props: ComparisonSlideProps): SlideComponent {
  return ({ size, theme }) => {
    const slide = createSlide(theme.colors.background);
    const heading = slideHeading({ title: props.title, eyebrow: props.eyebrow, bounds: { x: 0.72, y: 0.58, width: size.width - 1.44, height: 1 }, theme, component: "ComparisonSlide" });
    slide.add(...heading.elements);
    for (const warning of heading.warnings) slide.warn(warning);
    const panels = equalColumns({ x: 0.72, y: heading.contentTop, width: size.width - 1.44, height: size.height - heading.contentTop - 0.72 }, 2, theme.spacing.lg);
    const sides = [props.left, props.right] as const;
    panels.forEach((bounds, index) => {
      const panel = comparisonPanel(sides[index]!, bounds, theme, index === 0 ? "left" : "right");
      slide.add(...panel.elements);
      for (const warning of panel.warnings) slide.warn(warning);
    });
    const footer = footerElement(props.footer, theme, size.width, size.height);
    if (footer) slide.add(footer);
    return slide.build();
  };
}
